/**
 * Signal K Plugin: WIT WT901BLECL IMU Bluetooth Reader v17.2 (SIMPLE - NO AUTO CALIBRATION)
 * Streams: Attitude (roll/pitch/yaw), Acceleration (x/y/z in m/s²), Rate of Turn
 * 
 * Features:
 * - 100 Hz continuous streaming over BLE
 * - Auto-reconnection on disconnect
 * - Simple manual offsets only (no automatic scaling)
 * - Essential logging (connection events only)
 * - Production optimized
 */

const { spawn } = require('child_process')
const { execSync } = require('child_process')
const fs = require('fs')
const path = require('path')

module.exports = function(app) {
  const plugin = {}
  let pythonProcess = null
  let isConnected = false
  let reconnectTimer = null
  let lastDataTime = Date.now()
  let watchdogTimer = null
  let options = {}
  
  const watchdogTimeout = 10000
  const LOG_DIR = '/tmp/signalk-wit'
  const NODE_LOG = path.join(LOG_DIR, 'node.log')

  if (!fs.existsSync(LOG_DIR)) {
    fs.mkdirSync(LOG_DIR, { recursive: true })
  }

  const log = (msg) => {
    const line = `[${new Date().toISOString()}] ${msg}\n`
    try {
      fs.appendFileSync(NODE_LOG, line)
    } catch (e) {
      // Ignore log errors
    }
    app.debug(msg)
  }

  plugin.id = 'signalk-wit-imu-ble'
  plugin.name = 'WIT WT901BLECL IMU - Bluetooth'
  plugin.description = 'BLE Attitude, Acceleration, Angular Velocity @ 100Hz'

  plugin.schema = {
    type: 'object',
    properties: {
      bleAddress: { type: 'string', title: 'Bluetooth MAC Address', default: 'E9:10:DB:8B:CE:C7', description: 'WIT device MAC address' },
      updateRate: { type: 'number', title: 'Update Rate (Hz)', default: 100, enum: [20, 50, 100] },
      
      // Simple manual offsets only
      rollOffset: { type: 'number', title: 'Roll Offset (degrees)', default: 0, minimum: -180, maximum: 180 },
      pitchOffset: { type: 'number', title: 'Pitch Offset (degrees)', default: 0, minimum: -180, maximum: 180 },
      yawOffset: { type: 'number', title: 'Yaw Offset (degrees)', default: 0, minimum: -180, maximum: 180 },
      
      accelXOffset: { type: 'number', title: 'Accel X Offset (m/s²)', default: 0, minimum: -100, maximum: 100 },
      accelYOffset: { type: 'number', title: 'Accel Y Offset (m/s²)', default: 0, minimum: -100, maximum: 100 },
      accelZOffset: { type: 'number', title: 'Accel Z Offset (m/s²)', default: 0, minimum: -100, maximum: 100 },
      
      rateOfTurnZOffset: { type: 'number', title: 'Rate of Turn Z Offset (rad/s)', default: 0, minimum: -1, maximum: 1 }
    }
  }

  const disconnectFromBlueZ = (bleAddress) => {
    try {
      execSync(`bluetoothctl disconnect ${bleAddress}`, { timeout: 5000, stdio: 'ignore' })
      log('[BLUEZ] Disconnected')
    } catch (e) {
      // Ignore
    }
  }

  const createPythonScript = (bleAddress, updateRate) => {
    return `#!/usr/bin/env python3
import sys
sys.path.insert(0, '/home/aneto/witmotion_ble')
import asyncio, json
from bleak import BleakClient, BleakScanner
from WT901BLECL.wit_client import Wit901BLEClient
from WT901BLECL.time_handler import TimeHandler
from WT901BLECL.message import MsgType

class WITReader:
    def __init__(self, address):
        self.address = address.upper()
        self.stop_event = asyncio.Event()
        self.buffer = {}
        
    async def run(self):
        try:
            devices = await BleakScanner.discover(timeout=10)
            device = None
            for d in devices:
                if d.address.upper() == self.address.upper():
                    device = d
                    break
            
            if not device:
                print('[ERROR] Device not found', flush=True)
                sys.exit(1)
            
            print('[CONNECT] Creating BleakClient', flush=True)
            client = BleakClient(device, timeout=15)
            
            def on_disconnect(c):
                print('[DISCONNECT] Device offline', flush=True)
                self.stop_event.set()
            
            client.set_disconnected_callback(on_disconnect)
            
            print('[CONNECT] Creating Wit901BLEClient', flush=True)
            timer = TimeHandler(${updateRate})
            
            def callback(msg_list):
                if isinstance(msg_list, list):
                    for msg in msg_list:
                        if msg.type == MsgType.ANGLE:
                            self.buffer["attitude"] = {
                                "roll": float(msg.data[0] * 3.141592653589793 / 180.0),
                                "pitch": float(msg.data[1] * 3.141592653589793 / 180.0),
                                "yaw": float(msg.data[2] * 3.141592653589793 / 180.0)
                            }
                        elif msg.type == MsgType.ACCELERATION:
                            self.buffer["acceleration"] = {
                                "x": float(msg.data[0] * 9.81),
                                "y": float(msg.data[1] * 9.81),
                                "z": float(msg.data[2] * 9.81)
                            }
                        elif msg.type == MsgType.ANGULAR_VELOCITY:
                            self.buffer["angularVelocity"] = {
                                "x": float(msg.data[0]),
                                "y": float(msg.data[1]),
                                "z": float(msg.data[2])
                            }
                        
                        if "attitude" in self.buffer:
                            print(json.dumps(self.buffer), flush=True)
                            self.buffer = {}
                            break
            
            wit = Wit901BLEClient(_client=client, _timer=timer, _stream_callback=callback)
            
            print('[CONNECT] Connecting to device', flush=True)
            await wit.connect()
            print('[CONNECTED] WIT connected!', flush=True)
            
            print('[STREAM] Starting stream', flush=True)
            stream_task = asyncio.create_task(wit.stream())
            await self.stop_event.wait()
            
            print('[DISCONNECT] Stopping', flush=True)
            stream_task.cancel()
            try:
                await wit.disconnect()
            except:
                pass
            
        except Exception as e:
            print(f'[ERROR] {type(e).__name__}: {e}', flush=True)
            sys.exit(1)

reader = WITReader("${bleAddress}")
try:
    asyncio.run(reader.run())
except Exception as e:
    print(f'[ERROR] Top-level: {e}', flush=True)
    sys.exit(1)
`
  }

  const startWatchdog = () => {
    if (watchdogTimer) clearInterval(watchdogTimer)
    
    watchdogTimer = setInterval(() => {
      if (Date.now() - lastDataTime > watchdogTimeout && isConnected) {
        log('[WATCHDOG] No data - reconnecting')
        isConnected = false
        if (pythonProcess) pythonProcess.kill()
        triggerReconnect(false)
      }
    }, 2000)
  }

  const triggerReconnect = (isExpected = true) => {
    if (reconnectTimer) {
      clearTimeout(reconnectTimer)
      reconnectTimer = null
    }
    
    const delay = isExpected ? 3000 : 100
    log(isExpected ? '[RECONNECT] Scheduled (expected)' : '[RECONNECT] Immediate (device offline)')
    
    reconnectTimer = setTimeout(() => {
      log('[RECONNECT] Attempting...')
      reconnectTimer = null
      startConnection()
    }, delay)
  }

  const startConnection = () => {
    log('[CONNECT] Starting connection...')
    disconnectFromBlueZ(options.bleAddress)
    
    setTimeout(() => {
      log('[CONNECT] Spawning Python process')
      const pythonScript = createPythonScript(options.bleAddress, options.updateRate)
      app.setPluginStatus(`Connecting...`)
      
      pythonProcess = spawn('python3', ['-c', pythonScript], {
        stdio: ['ignore', 'pipe', 'pipe'],
        timeout: 0
      })

      log(`[CONNECT] PID: ${pythonProcess.pid}`)
      lastDataTime = Date.now()
      startWatchdog()

      let buffer = ''
      let dataPackets = 0

      pythonProcess.stdout.on('data', (data) => {
        const text = data.toString()
        
        // Log connection messages
        if (text.includes('[CONNECT]') || text.includes('[CONNECTED]') || text.includes('[ERROR]') || text.includes('[DISCONNECT]')) {
          log(text.trim())
        }
        
        buffer += text
        const lines = buffer.split('\n')
        
        for (let i = 0; i < lines.length - 1; i++) {
          const line = lines[i].trim()
          
          if (line.startsWith('{')) {
            try {
              const jdata = JSON.parse(line)
              dataPackets++
              lastDataTime = Date.now()
              
              if (dataPackets === 1) {
                isConnected = true
                app.setPluginStatus(`✅ Connected`)
                log('[STREAM] Data flowing')
              }
              
              const values = []
              
              // === ATTITUDE - Simple offset only ===
              if (jdata.attitude) {
                let roll = jdata.attitude.roll + (options.rollOffset || 0) * Math.PI / 180.0
                let pitch = jdata.attitude.pitch + (options.pitchOffset || 0) * Math.PI / 180.0
                let yaw = jdata.attitude.yaw + (options.yawOffset || 0) * Math.PI / 180.0
                
                values.push({ path: 'navigation.attitude.roll', value: roll })
                values.push({ path: 'navigation.attitude.pitch', value: pitch })
                values.push({ path: 'navigation.attitude.yaw', value: yaw })
              }
              
              // === ACCELERATION - Simple offset only (NO scaling) ===
              if (jdata.acceleration) {
                let accelX = jdata.acceleration.x + (options.accelXOffset || 0)
                let accelY = jdata.acceleration.y + (options.accelYOffset || 0)
                let accelZ = jdata.acceleration.z + (options.accelZOffset || 0)
                
                values.push({ path: 'navigation.acceleration.x', value: accelX })
                values.push({ path: 'navigation.acceleration.y', value: accelY })
                values.push({ path: 'navigation.acceleration.z', value: accelZ })
              }
              
              // === ANGULAR VELOCITY - Simple offset only ===
              if (jdata.angularVelocity) {
                let rotZ = jdata.angularVelocity.z + (options.rateOfTurnZOffset || 0)
                
                values.push({ path: 'navigation.rateOfTurn', value: rotZ })
                values.push({ path: 'navigation.angularVelocity.x', value: jdata.angularVelocity.x })
                values.push({ path: 'navigation.angularVelocity.y', value: jdata.angularVelocity.y })
                values.push({ path: 'navigation.angularVelocity.z', value: rotZ })
              }
              
              if (values.length > 0) {
                app.handleMessage(plugin.id, {
                  context: 'vessels.' + app.selfId,
                  updates: [{
                    source: { label: plugin.id },
                    timestamp: new Date().toISOString(),
                    values: values
                  }]
                })
              }
              
            } catch (e) {
              // Ignore parse errors
            }
          }
        }
        
        buffer = lines[lines.length - 1]
      })

      pythonProcess.on('close', (code) => {
        log(`[PROCESS] Exited (code ${code})`)
        isConnected = false
        app.setPluginStatus(`Reconnecting...`)
        const isDeviceDisconnect = (code === 0 && dataPackets > 0)
        triggerReconnect(!isDeviceDisconnect)
      })

    }, 3000)
  }

  plugin.start = function(opts) {
    opts = opts || {}
    options = opts
    
    log(`╔═══════════════════════════════╗`)
    log(`║ WIT IMU BLE v17.2 - SIMPLE    ║`)
    log(`║ Address: ${options.bleAddress}`)
    log(`║ Rate: ${options.updateRate} Hz`)
    log(`╚═══════════════════════════════╝`)
    
    app.setPluginStatus(`Initializing...`)
    startConnection()
  }

  plugin.stop = function() {
    log('[STOP] Plugin stopping')
    if (reconnectTimer) {
      clearTimeout(reconnectTimer)
      reconnectTimer = null
    }
    if (watchdogTimer) {
      clearInterval(watchdogTimer)
      watchdogTimer = null
    }
    if (pythonProcess) {
      pythonProcess.kill()
    }
    isConnected = false
  }

  return plugin
}
